import json
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    A = solver.IntVar(0, 6000, 'A')
    P = solver.IntVar(0, 4000, 'P')
    OM = solver.IntVar(0, 3000, 'OM')
    OMF = solver.IntVar(0, 7000, 'OMF')

    # Linearize the absolute value constraint
    D1 = solver.IntVar(-5000, 5000, 'D1')
    D2 = solver.IntVar(-5000, 5000, 'D2')
    solver.Add(A - OM == D1)
    solver.Add(OM - A == D2)

    # Add constraints
    solver.Add(A + P <= 10000)
    solver.Add(OM + OMF >= 2000)
    solver.Add(D1 <= 5000)
    solver.Add(D2 <= 5000)
    solver.Add(P - OMF >= -1000)

    # Define the objective function
    cost = 5 * A + 2 * P + 3 * OM + 4 * OMF
    solver.Minimize(cost)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = cost.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_cost
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

