import json
import numpy as np
from ortools.linear_solver import pywraplp

# Define the cities
cities = ['City 1', 'City 2', 'City 3', 'City 4']

# Define the travel costs between cities
costs = {
    ('City 1', 'City 2'): 29,
    ('City 1', 'City 3'): 97,
    ('City 1', 'City 4'): 72,
    ('City 2', 'City 1'): 29,
    ('City 2', 'City 3'): 69,
    ('City 2', 'City 4'): 52,
    ('City 3', 'City 1'): 97,
    ('City 3', 'City 2'): 69,
    ('City 3', 'City 4'): 91,
    ('City 4', 'City 1'): 72,
    ('City 4', 'City 2'): 52,
    ('City 4', 'City 3'): 91
}

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Create binary variables for each possible direct travel between cities
variables = {}
for i in cities:
    for j in cities:
        if i != j:
            variables[(i, j)] = solver.IntVar(0, 1, f'x_{i}_{j}')

# Ensure that each city is visited exactly once
for city in cities:
    incoming = solver.Sum(variables[(i, city)] for i in cities if i != city)
    outgoing = solver.Sum(variables[(city, j)] for j in cities if j != city)
    solver.Add(incoming == 1)
    solver.Add(outgoing == 1)

# Calculate the total travel cost
total_cost = solver.Sum(variables[(i, j)] * costs[(i, j)] for i in cities for j in cities if i != j)

# Minimize the total travel cost
solver.Minimize(total_cost)

# Solve the problem
status = solver.Solve()

# Extract the optimal solution
objective_value = total_cost.solution_value()

# Print the result
print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

