import json
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x11 = solver.IntVar(0, 5000, 'x11')
    x12 = solver.IntVar(0, 6000, 'x12')
    x21 = solver.IntVar(0, 5000, 'x21')
    x22 = solver.IntVar(0, 6000, 'x22')

    # Define the objective function
    profit = 9 * (x11 + x12) + 7 * (x21 + x22) - (2 * x11 + 4 * x12 + 2 * x21 + 3 * x22)
    solver.Maximize(profit)

    # Add constraints
    solver.Add(x11 + x21 <= 5000)
    solver.Add(x12 + x22 <= 6000)
    solver.Add(x11 + x12 <= 6000)
    solver.Add(x21 + x22 <= 7000)
    solver.Add(2 * x11 + 4 * x12 + 2 * x21 + 3 * x22 <= 45000)

    # Solve the problem
    status = solver.Solve()

    # Extract the objective value
    objective_value = profit.solution_value()

    # Determine the status
    if status == pywraplp.Solver.OPTIMAL:
        status_name = "OPTIMAL"
    else:
        status_name = "NOT_SOLVED"

    # Print the result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

