from ortools.linear_solver import pywraplp

def main():
    # Define the distance matrix
    distance_matrix = [
        [0, 86, 49, 57, 31, 69, 50],
        [86, 0, 68, 79, 93, 24, 5],
        [49, 68, 0, 16, 7, 72, 67],
        [57, 79, 16, 0, 90, 69, 1],
        [31, 93, 7, 90, 0, 86, 59],
        [69, 24, 72, 69, 86, 0, 81],
        [50, 5, 67, 1, 59, 81, 0]
    ]

    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Number of locations
    num_locations = 7

    # Create binary variables for each pair of locations
    x = {}
    for i in range(num_locations):
        for j in range(num_locations):
            if i != j:
                x[(i, j)] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Constraint: Each location is visited exactly once
    for i in range(num_locations):
        solver.Add(solver.Sum([x[(i, j)] for j in range(num_locations) if j != i]) == 1)

    # Constraint: The tour starts and ends at location 1
    solver.Add(x[(0, 1)] == 1)
    solver.Add(x[(1, 0)] == 1)

    # Objective: Minimize the total travel distance
    objective = solver.Objective()
    for i in range(num_locations):
        for j in range(num_locations):
            if i != j:
                objective.SetCoefficient(x[(i, j)], distance_matrix[i][j])
    objective.SetMinimization()

    # Solve the problem
    status = solver.Solve()

    # Extract the optimal tour
    tour = []
    for i in range(num_locations):
        for j in range(num_locations):
            if i != j and x[(i, j)].solution_value() > 0.5:
                tour.append((i, j))

    # Calculate the total distance
