    # Define decision variables
    x = solver.IntVar(0, 20, 'x')  # Number of ads in IJ
    y = solver.IntVar(0, 20, 'y')  # Number of ads in FS

    # Define auxiliary variables for IJ
    x1 = solver.IntVar(0, 6, 'x1')  # Ads 1-6
    x2 = solver.IntVar(0, 4, 'x2')  # Ads 7-10
    x3 = solver.IntVar(0, 5, 'x3')  # Ads 11-15

    # Define auxiliary variables for FS
    y1 = solver.IntVar(0, 6, 'y1')  # Ads 1-6
    y2 = solver.IntVar(0, 4, 'y2')  # Ads 7-10
    y3 = solver.IntVar(0, 5, 'y3')  # Ads 11-15

    # Constraints for IJ
    solver.Add(x1 <= x)
    solver.Add(x2 <= x - x1)
    solver.Add(x3 <= x - x1 - x2)

    # Constraints for FS
    solver.Add(y1 <= y)
    solver.Add(y2 <= y - y1)
    solver.Add(y3 <= y - y1 - y2)

    # Objective function
    objective = solver.Objective()
    objective.SetMaximization()

