# Define the cost matrix
cost_matrix = [
    [0, 21, 43, 25, 38, 91],
    [21, 0, 32, 25, 16, 14],
    [43, 32, 0, 96, 71, 98],
    [25, 25, 96, 0, 53, 22],
    [38, 16, 71, 53, 0, 100],
    [91, 14, 98, 22, 100, 0]
]

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Number of cities
num_cities = 6

# Create binary variables for each possible direct travel segment
x = {}
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            x[(i, j)] = solver.IntVar(0, 1, f'x_{i}_{j}')

# Objective function: minimize total travel cost
objective = solver.Objective()
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            objective.SetCoefficient(x[(i, j)], cost_matrix[i][j])
objective.SetMinimization()

# Constraint: Each city must be visited exactly once
for i in range(num_cities):
    incoming = solver.Sum([x[(j, i)] for j in range(num_cities) if j != i])
    outgoing = solver.Sum([x[(i, j)] for j in range(num_cities) if j != i])
    solver.Add(incoming == 1)
    solver.Add(outgoing == 1)

# Solve the problem
status = solver.Solve()

# Extract the optimal route
route = []
for i in range(num_cities):
    for j in range(num_cities):
        if i != j and x[(i, j)].solution_value() > 0.5:
            route.append((i, j))

# Calculate the total cost
total_cost = 0
for i, j in route:
    total_cost += cost_matrix[i][j]

# Print the result
print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

