    [10, 12, 11, 10, 19, 9, 0, 17, 1],  # Sector 6
    [0, 20, 15, 19, 20, 18, 14, 0, 8],  # Sector 7
    [16, 13, 3, 3, 20, 19, 2, 7, 0]   # Sector 8
]

# Create the solver
solver = pywraplp.Solver.CreateSolver("CBC_MIXED_INTEGER_PROGRAMMING")

# Create variables
num_sectors = 9
flow = [[solver.IntVar(0, capacity[i][j], f"flow_{i}_{j}") for j in range(num_sectors)] for i in range(num_sectors)]

# Objective: Maximize flow from sector 0 to sector 8
objective = solver.Objective()
objective.SetMaximization()
objective.SetCoefficient(flow[0][8], 1)

