    if i == 0:
        # Source node: total outflow is the total inflow to sector 8
        total_outflow = sum(flow[i][j] for j in range(num_sectors) if j != i)
        solver.Add(total_outflow == flow[0][8])
    elif i == 8:
        # Sink node: total inflow is the total outflow from sector 0
        total_inflow = sum(flow[j][i] for j in range(num_sectors) if j != i)
        solver.Add(total_inflow == flow[0][8])
    else:
        # Intermediate nodes: inflow equals outflow
        total_inflow = sum(flow[j][i] for j in range(num_sectors) if j != i)
        total_outflow = sum(flow[i][j] for j in range(num_sectors) if j != i)
        solver.Add(total_inflow == total_outflow)

