import numpy as np
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define the truck types and their parameters
    truck_types = ['TruckA', 'TruckB', 'TruckC', 'TruckD', 'TruckE']
    fuel_cost = [2, 3, 4, 5, 6]
    maintenance_cost = [1000, 1500, 2000, 2500, 3000]
    cargo_capacity = [10, 15, 20, 25, 30]

    # Create decision variables
    x = {}
    for i, truck_type in enumerate(truck_types):
        x[truck_type] = solver.IntVar(0, 30, f'x_{truck_type}')

    # Calculate total maintenance cost
    total_maintenance_cost = solver.Sum([maintenance_cost[i] * x[truck_types[i]] for i in range(len(truck_types))])

    # Calculate total fuel cost
    total_fuel_cost = solver.Sum([fuel_cost[i] * x[truck_types[i]] * 2000 for i in range(len(truck_types))])

    # Calculate total cargo capacity
    total_cargo_capacity = solver.Sum([cargo_capacity[i] * x[truck_types[i]] for i in range(len(truck_types))])

    # Objective: minimize total cost
    total_cost = total_maintenance_cost + total_fuel_cost
    solver.Minimize(total_cost)

    # Constraints
    solver.Add(total_maintenance_cost <= 100000)
    solver.Add(total_cargo_capacity >= 500)
    solver.Add(solver.Sum([x[truck_type] for truck_type in truck_types]) <= 30)

    # Solve the problem
    status = solver.Solve()

    # Calculate the objective value
    objective_value = total_cost.solution_value()

    # Calculate the cost per ton-kilometer
    if total_cargo_capacity.solution_value() > 0:
        cost_per_ton_kilometer = objective_value / total_cargo_capacity.solution_value()
    else:
        cost_per_ton_kilometer = float('inf')

    # Prepare the result
