from ortools.linear_solver import pywraplp

# Travel costs between cities
costs = {
    1: {2: 58, 3: 15, 4: 75, 5: 91},
    2: {1: 58, 3: 54, 4: 85, 5: 11},
    3: {1: 15, 2: 54, 4: 28, 5: 61},
    4: {1: 75, 2: 85, 3: 28, 5: 47},
    5: {1: 91, 2: 11, 3: 61, 4: 47}
}

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Number of cities
num_cities = 5

# Create binary variables for each edge
edges = {}
for i in range(1, num_cities + 1):
    for j in range(1, num_cities + 1):
        if i != j:
            edges[(i, j)] = solver.IntVar(0, 1, f'edge_{i}_{j}')

# Objective function
objective = solver.Objective()
for i in range(1, num_cities + 1):
    for j in range(1, num_cities + 1):
        if i != j:
            objective.SetCoefficient(edges[(i, j)], costs[i][j])

objective.SetMinimization()

# Constraints: Each city has exactly one incoming and one outgoing edge
for i in range(1, num_cities + 1):
